def _pg_open():
    from psycopg_pool import ConnectionPool  # pip install "psycopg[binary,pool]"
    pool = ConnectionPool(
        DATABASE_URL,
        min_size=2, max_size=8, open=False,
        max_lifetime=900,        # was 240: reconnecting every 4 minutes was too often
        max_idle=300,            # was 30
        reconnect_timeout=30,
        timeout=30,              # wait longer before giving up
        num_workers=3,
        kwargs={"autocommit": True, "connect_timeout": 15,
                "keepalives": 1, "keepalives_idle": 30,
                "keepalives_interval": 10, "keepalives_count": 5},
    )
    pool.open(wait=True, timeout=45)
    with pool.connection() as conn:
        with conn.transaction():
            conn.execute("SELECT pg_advisory_xact_lock(727274)")
            for stmt in PG_SCHEMA:
                conn.execute(stmt)
    return pool


def _pg(sql, params=(), fetch=None):
    import psycopg
    import psycopg_pool
    for attempt in (1, 2, 3):
        try:
            with PG.connection() as conn:
                cur = conn.execute(sql, params)
                if fetch == "one":
                    return cur.fetchone()
                if fetch == "all":
                    return cur.fetchall()
                return None
        except (psycopg.OperationalError, psycopg.InterfaceError, psycopg_pool.PoolTimeout) as e:
            if attempt == 3:
                raise
            print("database connection problem, retrying:", str(e)[:120])
            time.sleep(1.0 * attempt)


def _kb_conn():
    c = sqlite3.connect(DB_PATH, check_same_thread=False)
    c.execute("PRAGMA journal_mode=WAL")
    c.execute("CREATE VIRTUAL TABLE IF NOT EXISTS docs USING fts5("
              "content, title UNINDEXED, source UNINDEXED, tokenize='porter unicode61')")
    c.execute("CREATE TABLE IF NOT EXISTS sources(source TEXT PRIMARY KEY, chunks INT)")
    c.execute("CREATE TABLE IF NOT EXISTS messages("
              "id INTEGER PRIMARY KEY, session TEXT, role TEXT, content TEXT, "
              "ts DATETIME DEFAULT CURRENT_TIMESTAMP)")
    c.execute("CREATE TABLE IF NOT EXISTS users("
              "username TEXT PRIMARY KEY, pw TEXT NOT NULL, created DATETIME DEFAULT CURRENT_TIMESTAMP)")
    c.execute("CREATE TABLE IF NOT EXISTS memory("
              "id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL, fact TEXT NOT NULL, "
              "ts DATETIME DEFAULT CURRENT_TIMESTAMP)")
    return c


