def is_math(text):
    t = text or ""
    if re.search(r"\\frac|\$[^$]+\$", t):
        return True
    if re.search(r"\b(prove|show that|olympiad|find all)\b", t, re.I):
        return True
    return bool(MATH_STRONG.search(t)) and bool(re.search(r"\d|[=+^²³√]|\b[a-z]\s*[=<>]", t)) and len(t) >= 12


