@app.get("/privacy")
def privacy_page():
    return _legal("Privacy Policy", "<p>We store your username, your chats and the facts saved in Memory so the "
                  "service works. The site owner can read chats to run and improve the service. Messages are sent "
                  "to third-party AI providers to produce answers. You can delete chats and Memory inside the app. "
                  "Contact the owner to delete your account.</p>")

COST_PER_ANSWER = float(os.environ.get("DEEP_OQ_COST_PER_ANSWER", "0.01"))  # your estimate in USD


@app.get("/api/admin/stats")
def admin_stats():
    bad = _adm_guard()
    if bad:
        return bad
    rows = _adm_q("SELECT session, role, ts FROM messages WHERE ts >= datetime('now','-14 days')",
                  "SELECT session, role, ts FROM oq_messages WHERE ts >= now() - interval '14 days'")
    per_day, per_user = {}, {}
    for s, role, ts in rows:
        if role != "user":
            continue
        day, u = str(ts)[:10], _session_user(s)
        d = per_day.setdefault(day, {"users": set(), "questions": 0})
        d["users"].add(u)
        d["questions"] += 1
        per_user[u] = per_user.get(u, 0) + 1
    days = [{"day": k, "users": len(v["users"]), "questions": v["questions"],
             "cost": round(v["questions"] * COST_PER_ANSWER, 2)} for k, v in sorted(per_day.items(), reverse=True)]
    top = [{"user": u, "questions": n, "cost": round(n * COST_PER_ANSWER, 2)}
           for u, n in sorted(per_user.items(), key=lambda x: -x[1])[:15]]
    total_users = len(_adm_q("SELECT username FROM users", "SELECT username FROM oq_users"))
    return jsonify(days=days, top=top, total_users=total_users, cost_per_answer=COST_PER_ANSWER)


STATS_PAGE = r"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Deep OQ Stats</title>
<style>body{margin:0;background:#04050d;color:#eef0ff;font:15px system-ui,sans-serif;padding:20px;max-width:900px;margin:auto}
a{color:#00d4ff}h1{margin:0 0 6px}h2{margin:28px 0 8px;font-size:16px;color:#8e94b8}
.cards{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.c{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:14px 18px;min-width:150px}
.c b{display:block;font-size:26px}.c span{color:#8e94b8;font-size:13px}
table{width:100%;border-collapse:collapse}td,th{padding:8px 10px;text-align:left;border-bottom:1px solid rgba(255,255,255,.1)}
th{color:#8e94b8;font-weight:600;font-size:13px}.note{color:#8e94b8;font-size:13px}</style></head><body>
<a href="/admin">&larr; Admin</a><h1>Stats (last 14 days)</h1>
<div class="cards" id="cards"></div>
<h2>Per day</h2><table id="days"></table>
<h2>Top users</h2><table id="top"></table>
<p class="note" id="note"></p>
<script>
const $=s=>document.querySelector(s);
function row(t,cells,head){const tr=document.createElement('tr');cells.forEach(c=>{const e=document.createElement(head?'th':'td');e.textContent=c;tr.append(e)});t.append(tr)}
function card(v,l){const d=document.createElement('div');d.className='c';const b=document.createElement('b');b.textContent=v;const s=document.createElement('span');s.textContent=l;d.append(b,s);$('#cards').append(d)}
async function load(){
  const go=()=>fetch('/api/admin/stats',{headers:{'X-Access-Key':localStorage.ak||''}});
  let r=await go();
  if(r.status===401){localStorage.ak=prompt('Enter the access key')||'';r=await go()}
  const j=await r.json();
  if(!r.ok){$('#note').textContent=j.error||'Failed';return}
  const today=j.days[0]||{users:0,questions:0,cost:0};
  const q=j.days.reduce((a,d)=>a+d.questions,0),c=j.days.reduce((a,d)=>a+d.cost,0);
  card(j.total_users,'Total accounts');card(today.users,'Active users (latest day)');
  card(q,'Questions, 14 days');card('$'+c.toFixed(2),'Est. cost, 14 days');
  card('$'+(q?(c/q).toFixed(3):'0'),'Est. cost per question');
  row($('#days'),['Day','Active users','Questions','Est. cost'],true);
  j.days.forEach(d=>row($('#days'),[d.day,d.users,d.questions,'$'+d.cost.toFixed(2)]));
  row($('#top'),['User','Questions','Est. cost'],true);
  j.top.forEach(t=>row($('#top'),[t.user,t.questions,'$'+t.cost.toFixed(2)]));
  $('#note').textContent='Cost is an estimate: questions x $'+j.cost_per_answer+'. Set DEEP_OQ_COST_PER_ANSWER on Render to match your real average from your API billing pages.';
}
load();
</script></body></html>
"""


@app.get("/admin/stats")
def admin_stats_page():
    if not is_admin():
        return "Not found", 404
    return STATS_PAGE, 200, {"Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store"}
# ===== AGENT FILES: huge files (up to 100,000,000 characters), searched not stuffed =====
AF_DIR = os.path.join(tempfile.gettempdir(), "oq_agent_files")
os.makedirs(AF_DIR, exist_ok=True)
AF_MAX_CHARS = _env_int("OQ_FILE_MAX_CHARS", 100_000_000)
AF_MAX_BYTES = _env_int("OQ_FILE_MAX_MB", 100) * 1024 * 1024
AF_MAX_FILES = 6
AF_SECONDS = _env_int("OQ_FILE_SECONDS", 900)
_afiles = {}
_af_lock = threading.Lock()


def _af_db(fid):
    c = sqlite3.connect(os.path.join(AF_DIR, fid + ".db"), check_same_thread=False)
    c.execute("CREATE VIRTUAL TABLE IF NOT EXISTS c USING fts5(t, tokenize='porter unicode61')")
    return c


def _af_pieces(path, name):
    ext = os.path.splitext(name.lower())[1]
    if ext == ".pdf":
        from pypdf import PdfReader
        with open(path, "rb") as fh:
            reader = PdfReader(fh)
            seen = 0
            for i, pg in enumerate(reader.pages):
                t = pg.extract_text() or ""
                seen += len(t.strip())
                if i == 29 and seen < 200:
                    raise ValueError("This PDF looks scanned (no text). Upload photos of the pages instead.")
                yield t + "\n"
        return
    if ext == ".docx":
        import zipfile
        with zipfile.ZipFile(path) as z:
            xml = z.read("word/document.xml").decode("utf-8", "replace")
        yield _html.unescape(re.sub(r"<[^>]+>", "", xml.replace("</w:p>", "\n")))
        return
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        first = True
        while True:
            blk = fh.read(262144)
            if not blk:
                break
            if first and (blk.count("\x00") > 5 or blk.count("\ufffd") > 50):
                raise ValueError(name + " is not a readable text file.")
            first = False
            yield blk


def _af_ingest(fid, path, name):
    job = _afiles[fid]
    t0 = time.time()
    try:
        db = _af_db(fid)
        total = n = 0
        buf, rows = "", []
        for piece in _af_pieces(path, name):
            buf += piece
            total += len(piece)
            i = 0
            while len(buf) - i >= 1600:
                cut = buf.rfind("\n", i + 800, i + 1600)
                if cut < 0:
                    cut = buf.rfind(" ", i + 800, i + 1600)
                if cut < 0:
                    cut = i + 1600
                part = buf[i:cut].strip()
                i = cut
                if part:
                    n += 1
                    rows.append((n, part))
            buf = buf[i:]
            if len(rows) >= 400:
                db.executemany("INSERT INTO c(rowid, t) VALUES(?, ?)", rows)
                db.commit()
                rows = []
                job.update(chars=total, chunks=n)
            if total >= AF_MAX_CHARS or time.time() - t0 > AF_SECONDS:
                break
        if buf.strip():
            n += 1
            rows.append((n, buf.strip()))
        if rows:
            db.executemany("INSERT INTO c(rowid, t) VALUES(?, ?)", rows)
            db.commit()
        db.close()
        if n == 0:
            raise ValueError(name + " has no readable text.")
        job.update(state="ready", chars=min(total, AF_MAX_CHARS), chunks=n)
    except ImportError:
        job.update(state="error", error="PDF reading is not installed on the server (pip install pypdf).")
    except Exception as e:
        print("agent file failed:", e)
        job.update(state="error", error=str(e)[:200] or "Could not read this file.")
    finally:
        try:
            os.remove(path)
        except OSError:
            pass


def _af_owned(ids):
    user = login_session.get("user") or ""
    out = []
    for i in (ids or [])[:AF_MAX_FILES] if isinstance(ids, list) else []:
        j = _afiles.get(str(i))
        if j and j["user"] == user and j["state"] == "ready" and str(i) not in out:
            out.append(str(i))
    return out


def _af_search(fids, query, k=8):
    words = [w for w in re.findall(r"[\w\u0900-\u097F]{3,}", query.lower()) if w not in _STOP][:12]
    per = max(2, k // max(1, len(fids)))
    out = []
    for fid in fids:
        j = _afiles.get(fid)
        if not j or j["state"] != "ready":
            continue
        try:
            db = _af_db(fid)
            if words:
                rows = db.execute("SELECT rowid, t FROM c WHERE c MATCH ? ORDER BY bm25(c) LIMIT ?",
                                  (" OR ".join('"%s"' % w for w in words), per)).fetchall()
            else:
                rows = []
            db.close()
        except Exception as e:
            print("file search failed:", e)
            rows = []
        for rid, t in sorted(rows):
            out.append("[%s, part %d of %d]\n%s" % (j["name"], rid, j["chunks"], t))
    return "\n\n".join(out) or "No matching parts. Try different or fewer words, or use SUMMARY."


def _af_sample(fids, k=12):
    out = []
    per = max(3, k // max(1, len(fids)))
    for fid in fids:
        j = _afiles.get(fid)
        if not j or j["state"] != "ready":
            continue
        db = _af_db(fid)
        for s in range(per):
            rid = 1 + (s * (j["chunks"] - 1)) // max(1, per - 1) if j["chunks"] > 1 else 1
            r = db.execute("SELECT t FROM c WHERE rowid=?", (rid,)).fetchone()
            if r:
                out.append("[%s, part %d of %d]\n%s" % (j["name"], rid, j["chunks"], r[0]))
        db.close()
    return "\n\n".join(out)


def _agent_files(inp, job):
    fids = job.get("fids") or []
    if not fids:
        return "No files were uploaded."
    q = str(inp or "").strip()
    res = _af_sample(fids, 12) if q.upper().startswith("SUMMARY") else _af_search(fids, q, 8)
    return res[:6500]


def _af_prompt(fids):
    rows = "\n".join("- %s: %s characters in %d parts" % (_afiles[f]["name"], format(_afiles[f]["chars"], ","), _afiles[f]["chunks"]) for f in fids)
    return ("\nUPLOADED FILES (can be huge, so you cannot see them whole):\n" + rows +
            "\nUse tool 'files' to look inside: input = the search words for what you need (names, numbers, topic words), "
            "or the single word SUMMARY to get excerpts spread across the whole files. Search several times with different "
            "words before you answer. Never say something is not in the file until you have searched for it. "
            "Mention the file name when you use it.")


@app.post("/agent/upload")
def agent_upload():
    if denied():
        return jsonify(error="locked"), 401
    f = request.files.get("file")
    if not f or not f.filename:
        return jsonify(error="Choose a file first."), 400
    user = login_session.get("user") or ""
    name = re.sub(r"[\r\n]+", " ", f.filename)[:120]
    now = time.time()
    with _af_lock:
        for k in [k for k, v in _afiles.items() if now - v["t"] > 6 * 3600]:
            _afiles.pop(k, None)
            try:
                os.remove(os.path.join(AF_DIR, k + ".db"))
            except OSError:
                pass
        if sum(1 for v in _afiles.values() if v["user"] == user) >= 12:
            return jsonify(error="Too many uploaded files. Wait a while, then try again."), 429
        fid = uuid.uuid4().hex[:16]
        _afiles[fid] = {"user": user, "name": name, "t": now, "state": "working", "chars": 0, "chunks": 0}
    path = os.path.join(AF_DIR, fid + ".src")
    f.save(path)
    if os.path.getsize(path) > AF_MAX_BYTES:
        os.remove(path)
        _afiles.pop(fid, None)
        return jsonify(error="That file is over %d MB." % (AF_MAX_BYTES // 1048576)), 413
    threading.Thread(target=_af_ingest, args=(fid, path, name), daemon=True).start()
    return jsonify(id=fid, name=name)


@app.get("/agent/upload/<fid>")
def agent_upload_status(fid):
    j = _afiles.get(fid)
    if denied() or not j or j["user"] != (login_session.get("user") or ""):
        return jsonify(error="That file was lost because the server restarted. Please upload it again."), 404
    return jsonify(state=j["state"], chars=j["chars"], chunks=j["chunks"], error=j.get("error"))


