def _convert_any(x):
    v, a, b = _tba(x, 3)
    a, b = a.lower(), b.lower()
    if a not in _UN or b not in _UN:
        raise ValueError("unknown unit. Known: " + ", ".join(sorted(_UN)))
    return "%s %s = %s %s" % (_tbf(_tbn(v)), a, _tbf(_to_unit(_tbn(v), a, b)), b)


