# ---------------------------------------------------------------- generators
def _dice(x):
    m = re.fullmatch(r"\s*(\d*)d(\d+)\s*", x or "1d6")
    n, s = int(m.group(1) or 1), int(m.group(2))
    r = [secrets.randbelow(s) + 1 for _ in range(min(n, 100))]
    return "%s = %d" % (r, sum(r))


