def _ohm(x):
    v, i, r = _tba(x, 3)
    if v == "":
        return "V = %s V" % _tbf(_tbn(i) * _tbn(r))
    if i == "":
        return "I = %s A" % _tbf(_tbn(v) / _tbn(r))
    return "R = %s ohm" % _tbf(_tbn(v) / _tbn(i))


