    raw = f.read(SCAN46_MAX + 1)
    if len(raw) > SCAN46_MAX:
        return jsonify(error="That file is over %d MB. Use the Device scan for big files." % (SCAN46_MAX // 1048576)), 413
    if not raw:
        return jsonify(error="The file is empty."), 400
